def longest_ideal_subsequence(s,k):
    best=[0]*26
    for character in s:
        value=ord(character)-97
        length=1+max(best[max(0,value-k):min(26,value+k+1)],default=0)
        best[value]=max(best[value],length)
    return max(best,default=0)

